[CmdletBinding()]param([string]$PackageRoot)
$ErrorActionPreference='Stop';$PSNativeCommandUseErrorActionPreference=$false;if([string]::IsNullOrWhiteSpace($PackageRoot)){$PackageRoot=Split-Path -Parent $PSScriptRoot};$root=(Resolve-Path -LiteralPath $PackageRoot).Path;$payload=Join-Path $root payload;$pm=Get-Content -Raw -LiteralPath (Join-Path $root manifest.json)|ConvertFrom-Json;$nvcuda=Join-Path $env:WINDIR 'System32\nvcuda.dll';if(-not(Test-Path -LiteralPath $nvcuda)){throw'NVIDIA driver not found'};$required=@('neural_reference_probe.exe','n0_mma176_a_path_trace.ptx','n0_original.ptx','input_rgba16f.raw','weights.raw','params.raw');$actual=[ordered]@{};$integrity=$true;foreach($n in $required){$actual[$n]=(Get-FileHash -LiteralPath (Join-Path $payload $n)).Hash;$integrity=$integrity-and$actual[$n]-eq$pm.payload_sha256.$n};$x=[int]$pm.target_cta[0];$y=[int]$pm.target_cta[1];$stamp=Get-Date -Format yyyyMMdd_HHmmss;$work=Join-Path $root "_n0_cta${x}_${y}_mma176_a_path_work_$stamp";$result=Join-Path $root "_n0_cta${x}_${y}_mma176_a_path_trace_reference_result_$stamp";New-Item -ItemType Directory -Path $work,$result|Out-Null
function Run-Probe($ptx,$json,$scratch,$output,$log,[int]$extra){$args=@('--nvcuda',$nvcuda,'--ptx',$ptx,'--function',$pm.function,'--json',$json,'--n0-input',(Join-Path $payload input_rgba16f.raw),'--n0-weights',(Join-Path $payload weights.raw),'--n0-params',(Join-Path $payload params.raw),'--n0-scratch-out',$scratch,'--n0-output',$output,'--n0-grid-x','80','--n0-grid-y','48');if($extra-gt 0){$args+=@('--n0-scratch-extra-bytes',[string]$extra)};& (Join-Path $payload neural_reference_probe.exe) @args *> $log;return $LASTEXITCODE}
$pj=Join-Path $work probe.json;$scratch=Join-Path $work scratch.raw;$output=Join-Path $work output.raw;$pe=Run-Probe (Join-Path $payload n0_mma176_a_path_trace.ptx) $pj $scratch $output (Join-Path $work stdout.log) ([int]$pm.scratch_extra_bytes);$probe=Get-Content -Raw -LiteralPath $pj|ConvertFrom-Json;$bj=Join-Path $work baseline_probe.json;$bs=Join-Path $work baseline_scratch.raw;$bo=Join-Path $work baseline_output.raw;$be=Run-Probe (Join-Path $payload n0_original.ptx) $bj $bs $bo (Join-Path $work baseline_stdout.log) 0;$base=Get-Content -Raw -LiteralPath $bj|ConvertFrom-Json
$trace=Join-Path $result mma176_a_path_trace.raw;$s=[IO.File]::OpenRead($scratch);try{[void]$s.Seek([int64]$pm.trace_offset,[IO.SeekOrigin]::Begin);$b=[byte[]]::new([int]$pm.trace_bytes);$read=0;while($read-lt$b.Length){$n=$s.Read($b,$read,$b.Length-$read);if($n-eq 0){break};$read+=$n};if($read-ne$b.Length){throw"short trace $read"};[IO.File]::WriteAllBytes($trace,$b)}finally{$s.Dispose()};$nz=@($b|Where-Object{$_-ne 0}).Count;$oh=(Get-FileHash -LiteralPath $output).Hash;$bh=(Get-FileHash -LiteralPath $bo).Hash;$preserved=$oh-eq$bh;$pass=$integrity-and$pe-eq 0-and$probe.pass-and$be-eq 0-and$base.pass-and$preserved-and$nz-gt 0;Copy-Item $pj,$bj,(Join-Path $work stdout.log),(Join-Path $work baseline_stdout.log) -Destination $result
[ordered]@{schema=1;experiment='rtx_n0_selected_cta_mma176_a_path_trace';status=if($pass){'PASS'}else{'FAIL'};payload_integrity=$integrity;payload_sha256=$actual;probe_exit=$pe;probe_pass=[bool]$probe.pass;baseline_probe_exit=$be;baseline_probe_pass=[bool]$base.pass;device_name=$probe.device_name;grid=@(80,48,1);block=@(32,1,1);target_cta=$pm.target_cta;kernel_launched=[bool]$probe.kernel_launched;stage_count=[int]$pm.stage_count;stages=$pm.stages;checkpoint_bytes=[int]$pm.trace_bytes;checkpoint_nonzero_bytes=$nz;checkpoint_sha256=(Get-FileHash -LiteralPath $trace).Hash;scratch_extra_bytes=[int]$pm.scratch_extra_bytes;input_variant=$pm.input_variant;output_sha256=$oh;baseline_output_sha256=$bh;reference_output_preserved=$preserved;instrumentation_perturbed=(-not$preserved)}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $result manifest.json) -Encoding utf8;$zip="$result.zip";Compress-Archive -LiteralPath $result -DestinationPath $zip -CompressionLevel Optimal;Get-Content -Raw -LiteralPath (Join-Path $result manifest.json);Write-Host "Result: $zip";exit $(if($pass){0}else{1})
